import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int mod = sc.nextInt();

        int m = n * (n - 1) / 2;
        int size = n * (n - 1) + 1;

        int[][] dp = new int[n + 1][size];
        int[][] dp1 = new int[n + 1][size];

        dp[1][m] = 1;

        for (int i = 2; i <= n; i++) {
            int startX = m - (i - 1) * (i - 2) / 2;
            int endX = m + (i - 1) * (i - 2) / 2;

            // Update dp for each x
            for (int x = startX; x <= endX; x++) {
                for (int d = -i + 1; d < i; d++) {
                    int prevX = x;
                    int prevXIndex = prevX;
                    if (prevXIndex >= 0 && prevXIndex < size) {
                        int prevVal = dp[i - 1][prevXIndex];
                        int newVal = (int) (((long) prevVal * (i - Math.abs(d))) % mod);
                        int currentVal = dp[i][x];
                        int sumVal = currentVal + newVal;
                        if (sumVal >= mod) sumVal -= mod;
                        dp[i][x] = sumVal;
                    }
                }
            }

            // Update dp1 for each x
            for (int x = startX; x <= endX; x++) {
                int val = (int) (((long) dp1[i - 1][x] * i) % mod);
                dp1[i][x] = val;
            }

            for (int x = startX; x <= endX; x++) {
                for (int d = 1; d < i; d++) {
                    int targetX = x - d;
                    if (targetX >= 0 && targetX < size) {
                        long addVal = ((long) dp[i - 1][x] * (i - d)) % mod;
                        int sumVal = dp1[i][targetX] + (int) addVal;
                        if (sumVal >= mod) sumVal -= mod;
                        dp1[i][targetX] = sumVal;
                    }
                }
            }
        }

        long result = 0;
        for (int x = m + 1; x < size; x++) {
            result += dp1[n][x];
        }
        result %= mod;

        System.out.println(result);
        sc.close();
    }
}

